import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee, dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty list for empty invoices', () => {
  const r = overdueInvoices([], '2026-10-31');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const invoices = [inv];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 48854, date: '2026-10-15' }).value;

  const invoices = [paid];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 0);
});

test('overdueInvoices includes issued invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[0].dueDate, '2026-10-01');
  assert.equal(r[0].due, 48854);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 10000, date: '2026-10-15' }).value;

  const invoices = [partial];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 38854);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, issued.dueDate);
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-09-30');
  assert.equal(r.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // dueDate is 2026-10-01, asOf is 2026-10-31
  // daysOverdue = 30

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 30);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const invoices = [issued2, issued1, issued3];
  const r = overdueInvoices(invoices, '2026-11-20');
  assert.equal(r.length, 3);
  assert.ok(r[0].daysOverdue >= r[1].daysOverdue);
  assert.ok(r[1].daysOverdue >= r[2].daysOverdue);
});

test('overdueInvoices returns empty list when no invoices are overdue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-16',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = overdueInvoices(invoices, '2026-10-20');
  assert.equal(r.length, 0);
});

test('overdueInvoices filters by customerId in results', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 2);
  const c001 = r.find(inv => inv.customerId === 'C-001');
  const c002 = r.find(inv => inv.customerId === 'C-002');
  assert.ok(c001);
  assert.ok(c002);
});

test('overdueInvoices handles invoices with vouchers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'PROMO', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  // Total after voucher: 48854 - 5000 = 43854
  assert.equal(r[0].due, 43854);
});

test('overdueInvoices calculates due correctly for partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 20000, date: '2026-10-15' }).value;

  const invoices = [partial];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 28854);
});

test('overdueInvoices handles multiple payments on single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 10000, date: '2026-10-15' }).value;
  const partial2 = recordPayment(partial1, { amount: 15000, date: '2026-10-20' }).value;

  const invoices = [partial2];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 23854);
});

test('overdueInvoices includes invoice number in results', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
});

test('overdueInvoices includes dueDate in results', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = overdueInvoices(invoices, '2026-10-31');
