test('dashboard works with complex invoice mix', () => {
  const invoices = [];

  // Create multiple invoices in different statuses
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: i }],
    }).value;

    if (i === 1) {
      // Keep as draft
      invoices.push(inv);
    } else if (i === 2) {
      // Make it issued
      const issued = issueInvoice(inv, invoices.map(x => x.number || '')).value;
      invoices.push(issued);
    } else if (i === 3) {
      // Make it partially paid
      const issued = issueInvoice(inv, invoices.map(x => x.number || '')).value;
      const partial = recordPayment(issued, { amount: 15000, date: '2026-10-10' }).value;
      invoices.push(partial);
    } else if (i === 4) {
      // Make it paid
      const issued = issueInvoice(inv, invoices.map(x => x.number || '')).value;
      const paid = recordPayment(issued, { amount: issueInvoice(inv, invoices.map(x => x.number || '')).value.lines.reduce((s, l) => s + l.qty * l.unitPrice, 0) * 1.2, date: '2026-10-10' }).value;
      invoices.push(paid);
    } else {
      // Make it issued
      const issued = issueInvoice(inv, invoices.map(x => x.number || '')).value;
      invoices.push(issued);
    }
  }

  const result = dashboard(invoices, '2026-10-31');
  assert.equal(result.counts.draft, 1);
  assert.ok(result.counts.issued >= 2);
  assert.ok(result.outstanding > 0);
  assert.ok(result.topCustomers.length > 0);
});

